            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G2 and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                G2[k]=[[int(x) for x in r] for r in rows]
        G.update(G2)

def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                                seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,comp))
    return out

def f(g):
    h,w=len(g),len(g[0]); res=[r[:] for r in g]; noise=set()
    for c,comp in comps(g):
        has2x2=False
        for y,x in comp:
            if y+1<h and x+1<w and g[y+1][x]==c and g[y][x+1]==c and g[y+1][x+1]==c:
                has2x2=True; break
        if not has2x2: noise.update(comp)
    # deterministic tie-break: smallest color value among most-common
    for y,x in sorted(noise):
        nb=[g[a][b] for a in range(max(0,y-1),min(h,y+2)) for b in range(max(0,x-1),min(w,x+2)) if (a,b)!=(y,x)]
        cnt=Counter(nb)
        if cnt:
            mc=max(cnt.values())
            cand=[k for k,v in cnt.items() if v==mc]
            res[y][x]=min(cand) if cand else g[y][x]
        else:
            res[y][x]=g[y][x]
    return res

# sanity on demos
for i in range(1,9):
    k=f'Demo pair {i}'
    o=f(G[k+' input']); go=G[k+' output']
    print(k, o==go, json.dumps(o)==json.dumps(go) if o!=go else '')

out=f(G['Test input'])
print(json.dumps(out))
